            for (int k = 0; k < M; k++) {
                // Access A[i][k] using lower-triangular storage
                double a_ik = (i >= k) ? A[i][k] : A[k][i];
                temp += a_ik * B[k][j];
            }

            // Update C in place: C = alpha * A*B + beta * C
            C[i][j] = alpha * temp + beta * C[i][j];
        }
    }
}
